				"markdown": "****&#8592; Back to Aggregation List****",
				"fontSize": "large",
				"fontColor": "#53a051"
			},
			"eventHandlers": [
				{
					"type": "drilldown.linkToDashboard",
					"options": {
						"app": "CorelightForSplunk",
						"dashboard": "corelight_alert_aggregation"
					}
				}
			]
		},
		"viz_XYxdKOof": {
			"type": "splunk.table",
			"dataSources": {
				"primary": "ds_brGcXi0I"
			},
			"title": "Associated Connections (Click a uid to view associated logs)",
			"eventHandlers": [
				{
					"type": "drilldown.setToken",
					"options": {
						"tokens": [
							{
								"token": "uid",
								"key": "row.uid.value"
							}
						]
					}
				},
				{
					"type": "drilldown.setToken",
					"options": {
						"tokens": [
							{
								"token": "tokenuids",
								"key": "row.tokenuids.value"
							}
						]
					}
				}
			],
			"options": {
				"tableFormat": {
					"rowBackgroundColors": "> table | seriesByIndex(0) | pick(tableAltRowBackgroundColorsByTheme)"
				},
				"backgroundColor": "> themes.defaultBackgroundColor",
				"fontSize": "small",
				"columnFormat": {
					"ts": {
						"width": 126
					},
					"uid": {
						"width": 138,
						"data": "> table | seriesByName(\"uid\") | formatByType(uidColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"uid\") | matchValue(uidRowColorsEditorConfig)"
					},
					"Timestamp": {
						"width": 94,
						"data": "> table | seriesByName(\"Timestamp\") | formatByType(TimestampColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"Timestamp\") | matchValue(TimestampRowColorsEditorConfig)"
					},
					"UID": {
						"width": 136
					},
					"id.orig_h": {
						"width": 87
					},
					"Source": {
						"width": 82,
						"data": "> table | seriesByName(\"Source\") | formatByType(SourceColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"Source\") | matchValue(SourceRowColorsEditorConfig)"
					},
					"Destination": {
						"data": "> table | seriesByName(\"Destination\") | formatByType(DestinationColumnFormatEditorConfig)",
						"rowColors": "> table | seriesByName(\"Destination\") | matchValue(DestinationRowColorsEditorConfig)"
					}
				},
				"count": 40
			},
			"hideWhenNoData": true,
			"context": {
				"uidColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"uidRowColorsEditorConfig": [
					{
						"match": "",
						"value": "#ffffff"
					}
				],
				"TimestampColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"TimestampRowColorsEditorConfig": [
					{
						"match": "",
						"value": "#ffffffff"
					}
				],
				"SourceColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"SourceRowColorsEditorConfig": [
					{
						"match": "",
						"value": "#ffffffff"
					}
				],
				"DestinationColumnFormatEditorConfig": {
					"string": {
						"unitPosition": "after"
					}
				},
				"DestinationRowColorsEditorConfig": [
					{
						"match": "",
						"value": "#ffffffff"
					}
				]
			}
		},
