	"dataSources": {
		"ds_rqBAwdqt": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_BM7jZdrv",
				"query": "| stats max(impact_score) as max_impact_score",
				"enableSmartSources": true
			},
			"name": "alert_aggregations_count_impact_max_top"
		},
		"ds_BM7jZdrv": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_evt_aggregations`  did=\"$agg_id$\"\n| eval sid = mvappend(sid, 'sid{}')\n| eval signature = mvappend(signatures, 'signatures{}')\n| lookup corelight_alert_aggregations sid OUTPUT sid as lookup_sid impact_score category technique_number attack_phase technique_name sub_technique_name sub_technique_number attack_reason traffic_direction cve_number cve_creation_date cve_impact_score cve_exploitability_score cve_description impact_score_reason tags\n| eval in_lookup=if(isnull(lookup_sid), \"no\", \"yes\")\n| search in_lookup=\"yes\"\n| table *",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_top"
		},
		"ds_ByucTC8g": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_BM7jZdrv",
				"query": "| stats dc(cve_number) as cve_count by did",
				"enableSmartSources": true
			},
			"name": "alert_aggregations_CVE_Count"
		},
		"ds_mGnn2s7I": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_BM7jZdrv",
				"query": "| dedup did\n| table sid signature impact_score attack_phase category technique_name technique_number traffic_direction\n| rename sid as SIDs, signatures as Signatures, impact_score as \"Impact Score\", attack_phase as \"MITRE Attack Phase\", category as Category, technique_name as \"MITRE Tech\", technique_number as \"Tech. #\", traffic_direction as \"Traffic Dir.\""
			},
			"name": "alert_aggregations_assoc_alerts_list"
		},
		"ds_vp42MGT9": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_nyBv5HNY",
				"query": "| stats values(cve_number) as cve_number",
				"enableSmartSources": true
			},
			"name": "alert_aggregations_cve_numbers"
		},
		"ds_SzlZyoTK": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_BM7jZdrv",
				"query": "| stats max(cve_impact_score) as cve_impact_score\n| table cve_impact_score"
			},
			"name": "alert_aggregations_detail_cve_impact_top"
		},
		"ds_brGcXi0I": {
			"type": "ds.search",
			"options": {
				"query": "eventtype=corelight_aggregations did=$agg_id$\n| eval sid = mvappend(sid, 'sid{}')\n| eval ts = mvappend(ts, 'ts{}')\n```| eventstats values(uid) as all_uids, first(ts) as ts```\n| eval signature = mvappend(signature, 'signature{}')\n| eval paths = mvappend(paths, 'paths{}')\n| rex field=paths \"(?<=corelight_)(?<last_part>\\w+)\"\n| eval ts = strftime(strptime(ts, \"%Y-%m-%dT%H:%M:%S.%6NZ\"), \"%m-%d-%Y %H:%M:%S\")\n| dedup uid\n| eventstats values(uid) as all_uids\n| eventstats first(ts) as ts by uid\n| eval tokenuids = mvjoin(all_uids, \",\")\n| table uid ts id.orig_h id.resp_h \n| rename uid as uid, ts as Timestamp, id.orig_h as Source, id.resp_h as Destination",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_uid_list"
		},
		"ds_4IWGGYU7": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx`\n| eval source=\"$source$\"\n| eval target_sourcetype = case(\n    source==\"conn\", \"corelight_conn\",\n    source==\"http\", \"corelight_http\",\n    source==\"ssl\", \"corelight_ssl\",\n    source==\"dns\", \"corelight_dns\",\n    source==\"files\", \"corelight_files\",\n    source==\"smb\", \"corelight_smb_mapping\"\n)\n| where sourcetype = target_sourcetype \n| search uid = $uid$\n| eval spcap_link = \"<a href=\\\"\" . 'spcap.url' . \"\\\" target=\\\"_blank\\\">\" . 'spcap.url' . \"</a>\"\n",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_events_dynamic_display"
		},
		"ds_SI79AqlY": {
			"type": "ds.search",
			"options": {
				"enableSmartSources": true,
				"query": "`corelight_idx` `corelight_evt_aggregations` uid=$uid$\n| eval paths = mvappend(paths, 'paths{}')\n| eval \n    Conn = if(match(paths, \"corelight_conn\"), 1, 0),\n    HTTP = if(match(paths, \"corelight_http\"), 1, 0),\n    SSL = if(match(paths, \"corelight_ssl\"), 1, 0),\n    DNS = if(match(paths, \"corelight_dns\"), 1, 0),\n    Files = if(match(paths, \"corelight_files\"), 1, 0),\n    SMB = if(match(paths, \"corelight_smb_mapping\"), 1, 0)\n| stats values(tokenuids), max(Conn) as Conn, max(HTTP) as HTTP, max(SSL) as SSL, max(DNS) as DNS, max(Files) as Files, max(SMB) as SMB",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "alert_aggregations_details_srctypes_menu"
		},
		"ds_5TjlL87O": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| stats values(HTTP) as HTTP"
			},
			"name": "alert_aggregations_details_http_menu"
		},
		"ds_rgR9aveX": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| table Conn"
			},
			"name": "alert_aggregations_detail_conn_menu_select"
		},
		"ds_f4xhz1G8": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| table SSL"
			},
			"name": "alert_aggregations_details_ssl_menu_seleect"
		},
		"ds_BXY2kpBE": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| table Files"
			},
			"name": "alert_aggregations_details_files_menu_select"
		},
		"ds_Ps2FkPXx": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| table DNS"
			},
			"name": "alert_aggregations_details_dns_menu_select"
		},
		"ds_IEEQ46tU": {
			"type": "ds.chain",
			"options": {
				"extend": "ds_SI79AqlY",
				"query": "| table SMB"
			},
			"name": "alert_aggregations_details_smb_select_menu"
		},
		"ds_TjQHRTDH": {
			"type": "ds.chain",
			"options": {
				"enableSmartSources": true,
				"extend": "ds_brGcXi0I",
				"query": "| eventstats values(UID) as all_uids\n| eval tokenuids = mvjoin(all_uids, \",\")\n| dedup tokenuids\n| table tokenuids"
			},
			"name": "alert_aggregations_details_uids_dropdown"
		},
		"ds_nyBv5HNY": {
			"type": "ds.chain",
			"options": {
				"enableSmartSources": true,
				"extend": "ds_BM7jZdrv",
				"query": "| stats dc(id.orig_h) as total_sources, dc(id.resp_h) as total_dest, dc(uid) as unique_uids, dc(cve_number) as unique_cve_count, values(cve_number) as cve_number, values(cve_creation_date) as cve_creation_date, values(attack_reason) as attack_reason\n| `dynamic_format_high_counts`"
			},
			"name": "alert_aggregations_details_metadata_top"
		},
		"ds_mht8x8sn": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_st_suricata` uid=$uid$ \n| eval clicked_value=\"$payloadtoken$\"\n| fields payload, uid, alert.signature_id\n| rename alert.signature_id as sid\n| eval decoded_payload = if(isnotnull(sid) AND (isnull(payload) OR payload==\"\"), \"No payload available\", null())\n| where isnotnull(sid)\n| eval converts=split(payload,\"\")\n|  lookup corelight_base64conversion index as converts OUTPUT value as base64bin\n| eval bin_combined=mvjoin(base64bin,\"\")\n| eval bin_chunked=split(replace(bin_combined, \"(.{8})\", \"\\1,\"), \",\") \n| lookup corelight_base64conversion index as bin_chunked OUTPUT value as ascii\n| rex field=ascii mode=sed \"s/\\~/ /g\"\n| eval decoded_payload = if(isnull(decoded_payload), mvjoin(ascii,\"\"), decoded_payload)\n| eval combined = sid + \":::\" + coalesce(payload, \"\") + \":::\" + decoded_payload\n| stats values(combined) as combined_values by uid\n| mvexpand combined_values\n| eval sid=mvindex(split(combined_values, \":::\"), 0)\n| eval payload=mvindex(split(combined_values, \":::\"), 1)\n| eval decoded_payload=mvindex(split(combined_values, \":::\"), 2)\n| stats list(sid) as SIDs, list(decoded_payload) as \"Decoded Payloads\" by uid payload\n| fields SIDs, \"Decoded Payloads\"",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_payloads"
		},
		"ds_OIBg5giw": {
			"type": "ds.search",
			"options": {
				"query": "eventtype=corelight_suri uid=$uid$\n| search payload = *",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				}
			},
			"name": "alert_aggregations_details_suricata_payloads"
		},
		"ds_4xuIfxj2_ds_OIBg5giw": {
			"type": "ds.search",
			"options": {
				"query": "`corelight_idx` `corelight_evt_conn`uid=$uid$ \n| eval connlog=\"$alert_aggregations_events_dynamic_display:result.target_sourcetype$\"\n| where connlog=\"corelight_conn\"\n| search  spcap.url = * \n| stats count(spcap.url) as count last(spcap.url) as spcap.url",
				"queryParameters": {
					"earliest": "$global_time.earliest$",
					"latest": "$global_time.latest$"
				},
				"enableSmartSources": true
			},
			"name": "alert_aggregations_details_spcapurl_link"
		}
	},
